import * as THREE from '/static/vendor/three/three.module.js';

// ─── GLB DATA (Base64 embebido) ───────────────────────────────────────────────
const GLB_B64 ="data:application/octet-stream;base64,";

// ─── GLB BINARY PARSER ────────────────────────────────────────────────────────
function parseGLB(arrayBuffer) {
  const view   = new DataView(arrayBuffer);
  const magic  = String.fromCharCode(...new Uint8Array(arrayBuffer, 0, 4));
  if (magic !== 'glTF') throw new Error('Not a valid GLB file');

  const totalLen = view.getUint32(8, true);
  let   offset   = 12;
  let   jsonStr  = null;
  let   binBuf   = null;

  while (offset < totalLen) {
    const chunkLen  = view.getUint32(offset,     true); offset += 4;
    const chunkType = view.getUint32(offset,     true); offset += 4;
    if (chunkType === 0x4E4F534A) {                      // JSON
      jsonStr = new TextDecoder().decode(new Uint8Array(arrayBuffer, offset, chunkLen));
    } else if (chunkType === 0x004E4942) {               // BIN
      binBuf = arrayBuffer.slice(offset, offset + chunkLen);
    }
    offset += chunkLen;
  }
  if (!jsonStr) throw new Error('GLB: no JSON chunk');
  return { json: JSON.parse(jsonStr), bin: binBuf || new ArrayBuffer(0) };
}

// ─── MINIMAL GLTF PARSER ─────────────────────────────────────────────────────
// Compatible con ES6 modules, sin herencia de THREE.Loader
class GLTFParser {
  constructor(json, bin) {
    this.json     = json;
    this.bin      = bin;
    this._cache   = new Map();
    this._texCache = new Map();
    this._names   = new Set();
    this._texLoader = new THREE.TextureLoader();

    // Tabla de tipos de componentes WebGL
    this._CTYPES = {
      5120: Int8Array, 5121: Uint8Array, 5122: Int16Array,
      5123: Uint16Array, 5125: Uint32Array, 5126: Float32Array,
    };
    this._TSIZES = { SCALAR:1, VEC2:2, VEC3:3, VEC4:4, MAT2:4, MAT3:9, MAT4:16 };
    this._ATTRS  = {
      POSITION:'position', NORMAL:'normal', TANGENT:'tangent',
      TEXCOORD_0:'uv', TEXCOORD_1:'uv2', COLOR_0:'color',
      WEIGHTS_0:'skinWeight', JOINTS_0:'skinIndex',
    };
    this._FILTERS = {
      9728: THREE.NearestFilter, 9729: THREE.LinearFilter,
      9984: THREE.NearestMipmapNearestFilter, 9985: THREE.LinearMipmapNearestFilter,
      9986: THREE.NearestMipmapLinearFilter,  9987: THREE.LinearMipmapLinearFilter,
    };
    this._WRAPS = {
      33071: THREE.ClampToEdgeWrapping,
      33648: THREE.MirroredRepeatWrapping,
      10497: THREE.RepeatWrapping,
    };
  }

  // ── Punto de entrada ──────────────────────────────────────────────────────
  async parseScene() {
    const sceneIdx = this.json.scene ?? 0;
    return this._scene(sceneIdx);
  }

  // ── Helpers de caché ──────────────────────────────────────────────────────
  _dep(type, idx) {
    const key = `${type}:${idx}`;
    if (!this._cache.has(key)) {
      const p = this[`_${type}`](idx);
      this._cache.set(key, p);
    }
    return this._cache.get(key);
  }

  // ── BufferView ────────────────────────────────────────────────────────────
  _bufferView(idx) {
    const def = this.json.bufferViews[idx];
    const off = def.byteOffset ?? 0;
    const len = def.byteLength ?? 0;
    return Promise.resolve(this.bin.slice(off, off + len));
  }

  // ── Accessor ──────────────────────────────────────────────────────────────
  async _accessor(idx) {
    const def    = this.json.accessors[idx];
    const iSize  = this._TSIZES[def.type];
    const TA     = this._CTYPES[def.componentType];
    const eB     = TA.BYTES_PER_ELEMENT;
    const bOff   = def.byteOffset ?? 0;
    const norm   = def.normalized === true;

    if (def.bufferView === undefined) {
      return new THREE.BufferAttribute(new TA(def.count * iSize), iSize, norm);
    }

    const bv    = await this._dep('bufferView', def.bufferView);
    const bvDef = this.json.bufferViews[def.bufferView];
    const stride = bvDef.byteStride;
    const iB    = eB * iSize;

    if (stride && stride !== iB) {
      const slc   = Math.floor(bOff / stride);
      const ibKey = `ib:${def.bufferView}:${def.componentType}:${slc}`;
      if (!this._cache.has(ibKey)) {
        const arr = new TA(bv, slc * stride, def.count * stride / eB);
        this._cache.set(ibKey, new THREE.InterleavedBuffer(arr, stride / eB));
      }
      const ib = this._cache.get(ibKey);
      return new THREE.InterleavedBufferAttribute(ib, iSize, (bOff % stride) / eB, norm);
    }

    const arr = new TA(bv, bOff, def.count * iSize);
    return new THREE.BufferAttribute(arr, iSize, norm);
  }

  // ── Texture ───────────────────────────────────────────────────────────────
  async _texture(idx) {
    const texDef = this.json.textures[idx];
    const srcDef = this.json.images[texDef.source];
    const key    = `tex:${idx}`;
    if (this._texCache.has(key)) return this._texCache.get(key);

    let texPromise;
    if (srcDef.bufferView !== undefined) {
      texPromise = this._dep('bufferView', srcDef.bufferView).then(bv => {
        const blob = new Blob([bv], { type: srcDef.mimeType || 'image/jpeg' });
        const uri  = URL.createObjectURL(blob);
        return new Promise((res, rej) => {
          this._texLoader.load(uri, t => { URL.revokeObjectURL(uri); res(t); }, undefined, rej);
        });
      });
    } else {
      texPromise = new Promise((res, rej) =>
        this._texLoader.load(srcDef.uri || '', res, undefined, rej));
    }

    const p = texPromise.then(tex => {
      tex.flipY = false;
      const samps  = this.json.samplers || [];
      const samp   = samps[texDef.sampler] || {};
      tex.magFilter = this._FILTERS[samp.magFilter] || THREE.LinearFilter;
      tex.minFilter = this._FILTERS[samp.minFilter] || THREE.LinearMipmapLinearFilter;
      tex.wrapS     = this._WRAPS[samp.wrapS] || THREE.RepeatWrapping;
      tex.wrapT     = this._WRAPS[samp.wrapT] || THREE.RepeatWrapping;
      return tex;
    });
    this._texCache.set(key, p);
    return p;
  }

  // ── Material ──────────────────────────────────────────────────────────────
  async _material(idx) {
    const def  = this.json.materials[idx];
    const mr   = def.pbrMetallicRoughness || {};
    const params = {};
    const tasks  = [];

    params.color   = new THREE.Color(1, 1, 1);
    params.opacity = 1;
    if (Array.isArray(mr.baseColorFactor)) {
      params.color.setRGB(mr.baseColorFactor[0], mr.baseColorFactor[1], mr.baseColorFactor[2]);
      params.opacity = mr.baseColorFactor[3];
    }
    if (mr.baseColorTexture != null)
      tasks.push(this._dep('texture', mr.baseColorTexture.index)
        .then(t => { t.encoding = THREE.sRGBEncoding; params.map = t; }));

    params.metalness = mr.metallicFactor  ?? 1;
    params.roughness = mr.roughnessFactor ?? 1;

    if (mr.metallicRoughnessTexture != null)
      tasks.push(this._dep('texture', mr.metallicRoughnessTexture.index)
        .then(t => { params.metalnessMap = t; params.roughnessMap = t; }));
    if (def.normalTexture != null)
      tasks.push(this._dep('texture', def.normalTexture.index)
        .then(t => { params.normalMap = t; }));
    if (def.occlusionTexture != null)
      tasks.push(this._dep('texture', def.occlusionTexture.index)
        .then(t => { params.aoMap = t; }));
    if (def.emissiveFactor)
      params.emissive = new THREE.Color().fromArray(def.emissiveFactor);
    if (def.emissiveTexture != null)
      tasks.push(this._dep('texture', def.emissiveTexture.index)
        .then(t => { t.encoding = THREE.sRGBEncoding; params.emissiveMap = t; }));

    if (def.doubleSided) params.side = THREE.DoubleSide;
    const am = def.alphaMode || 'OPAQUE';
    if (am === 'BLEND') { params.transparent = true; params.depthWrite = false; }
    else if (am === 'MASK') params.alphaTest = def.alphaCutoff ?? 0.5;

    await Promise.all(tasks);
    const mat = new THREE.MeshStandardMaterial(params);
    if (def.name) mat.name = def.name;
    return mat;
  }

  // ── Geometry (single primitive) ───────────────────────────────────────────
  async _geometry(prim) {
    const geo   = new THREE.BufferGeometry();
    const tasks = [];

    for (const [name, accessorIdx] of Object.entries(prim.attributes)) {
      const attrName = this._ATTRS[name] || name.toLowerCase();
      if (attrName in geo.attributes) continue;
      tasks.push(
        this._dep('accessor', accessorIdx).then(acc => geo.setAttribute(attrName, acc))
      );
    }
    if (prim.indices != null)
      tasks.push(this._dep('accessor', prim.indices).then(acc => geo.setIndex(acc)));

    await Promise.all(tasks);
    // Garantizar uv2 para aoMap
    if (!geo.attributes.uv2 && geo.attributes.uv)
      geo.setAttribute('uv2', geo.attributes.uv);
    return geo;
  }

  // ── Mesh ──────────────────────────────────────────────────────────────────
  async _mesh(idx) {
    const meshDef = this.json.meshes[idx];
    const prims   = meshDef.primitives;

    const [mats, geos] = await Promise.all([
      Promise.all(prims.map(p =>
        p.material != null
          ? this._dep('material', p.material)
          : Promise.resolve(new THREE.MeshStandardMaterial({ color: 0xcccccc }))
      )),
      Promise.all(prims.map(p => this._geometry(p))),
    ]);

    const meshes = prims.map((_, i) => {
      const geo = geos[i];
      const mat = mats[i];
      if (geo.attributes.color) mat.vertexColors = true;
      if (!geo.attributes.normal) mat.flatShading = true;
      const mesh = new THREE.Mesh(geo, mat);
      mesh.castShadow    = true;
      mesh.receiveShadow = true;
      return mesh;
    });

    if (meshes.length === 1) return meshes[0];
    const group = new THREE.Group();
    meshes.forEach(m => group.add(m));
    return group;
  }

  // ── Node ──────────────────────────────────────────────────────────────────
  async _node(idx) {
    const def  = this.json.nodes[idx];
    const objs = [];

    if (def.mesh != null) objs.push(await this._dep('mesh', def.mesh));

    let node;
    if (objs.length === 1) node = objs[0];
    else { node = new THREE.Group(); objs.forEach(o => node.add(o)); }

    if (def.name) node.name = def.name;

    if (def.matrix) {
      node.applyMatrix4(new THREE.Matrix4().fromArray(def.matrix));
    } else {
      if (def.translation) node.position.fromArray(def.translation);
      if (def.rotation)    node.quaternion.fromArray(def.rotation);
      if (def.scale)       node.scale.fromArray(def.scale);
    }
    return node;
  }

  // ── Scene ─────────────────────────────────────────────────────────────────
  async _scene(idx) {
    const def  = this.json.scenes[idx];
    const root = new THREE.Group();
    if (def.name) root.name = def.name;

    const buildHierarchy = async (nodeId, parent) => {
      const node = await this._dep('node', nodeId);
      parent.add(node);
      const children = this.json.nodes[nodeId].children || [];
      await Promise.all(children.map(cid => buildHierarchy(cid, node)));
    };

    await Promise.all((def.nodes || []).map(id => buildHierarchy(id, root)));
    return root;
  }
}

// ─── FUNCIÓN PRINCIPAL EXPORTADA ──────────────────────────────────────────────
/**
 * createElogioEspanha(scene)
 *
 * @param {THREE.Scene} scene  — la escena principal de asturias-scene.js
 * @returns {{ group: THREE.Group, update: (t: number) => void }}
 *
 * group.position  → ajusta posición en la escena (default: x=0, y=0.35, z=-0.8)
 * group.visible   → muestra/oculta el modelo
 * update(t)       → llama en cada frame dentro de animate()
 */
export async function createElogioEspanha(scene) {

  // ── 1. Decodificar el GLB desde Base64 ────────────────────────────────────
  /*const binStr = atob(GLB_B64);
  const bytes  = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  const { json, bin } = parseGLB(bytes.buffer);*/

  // ── 1. Decodificar el GLB desde Base64 (CON LIMPIEZA) ──────────────────────
  // Paso A: Quitamos el prefijo "data:...base64," si es que existe
  const base64Raw = GLB_B64.includes(',') ? GLB_B64.split(',')[1] : GLB_B64;
  
  // Paso B: Quitamos espacios, saltos de línea o retornos de carro
  const base64Clean = base64Raw.replace(/\s/g, '');

  let binStr;
  try {
    binStr = atob(base64Clean);
  } catch (e) {
    console.error("Error en atob: El string Base64 no es válido. Revisa si copiaste el código completo.");
    throw e;
  }

  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  
  const { json, bin } = parseGLB(bytes.buffer);

  // ── 2. Parsear la escena GLTF ─────────────────────────────────────────────
  const parser   = new GLTFParser(json, bin);
  const gltfRoot = await parser.parseScene();

  // ── 3. Ajustar escala y orientación del modelo ────────────────────────────
  // El modelo Google Earth viene muy grande → normalizamos a ≈ 1 unidad de ancho
  const box     = new THREE.Box3().setFromObject(gltfRoot);
  const size    = box.getSize(new THREE.Vector3());
  const maxDim  = Math.max(size.x, size.y, size.z);
  const TARGET_SIZE = 0.2;                    // ancho deseado en unidades de la escena
  const scaleFactor = TARGET_SIZE / maxDim;

  gltfRoot.scale.setScalar(scaleFactor);

  // Recentrar en origen local (el modelo no siempre está centrado en 0,0,0)
  const box2   = new THREE.Box3().setFromObject(gltfRoot);
  const center = box2.getCenter(new THREE.Vector3());
  gltfRoot.position.sub(center);             // centrar horizontalmente
  gltfRoot.position.y = 0;                   // base en Y=0 del grupo

  // ── 4. Grupo contenedor con posición en la escena ─────────────────────────
  const group = new THREE.Group();
  group.name  = 'elogio_espanha';

  // ── POSICIÓN por defecto ──────────────────────────────────────────────────
  // Coordenadas de la escena de Asturias:
  //   X: eje horizontal del mapa  (-7.2 … +7.2)
  //   Y: altura sobre el suelo    (0 = nivel base de las plataformas)
  //   Z: eje vertical del mapa    (-3.5 sur … +1.6 costa norte)
  //
  // Esta posición coloca el modelo en la zona centro-sur del mapa,
  // levantado sobre una plataforma típica (depth ≈ 0.10-0.15 → Y ≈ 0.30-0.45)
  group.position.set(
    0,   // X: ligeramente al oeste del centro
    0,  // Y: encima del nivel de la isla flotante / plataforma elevada
    0   // Z: zona interior del mapa (no en la costa)
  );

  group.add(gltfRoot);
  scene.add(group);

  // ── 5. Sombra proyectada desde la escena principal ────────────────────────
  // Usamos la misma luz ambiental + lambertiana ya existente.
  // El modelo tiene MeshStandardMaterial con texturas → se ve bien con
  // la iluminación existente de la escena (AmbientLight + luz cenital).

  // ── 6. Estado de animación decorativa ─────────────────────────────────────
  // Animación sutil: levitación suave + rotación Y lenta
  const HOVER_AMP   = 0;   // amplitud vertical (unidades de escena)
  const HOVER_FREQ  = 0;    // Hz de la oscilación
  const ROT_SPEED   = 0;    // rad/s de rotación Y

  const baseY = 0; 
  function update(t) {
      if (!t) return;
      // Esto hará que flote un poquito sobre la plataforma (0.03 + oscilación)
      group.position.y = baseY + Math.sin(t * HOVER_FREQ * Math.PI * 2) * HOVER_AMP;
      group.rotation.y = t * ROT_SPEED;
  }

  // ── 8. API pública ─────────────────────────────────────────────────────────
  return { group, update};
}